let selected = data[0];

function key(day){ return 'okinawa-web-techo-memo-2026-01-' + day; }
function getMemo(day){ return localStorage.getItem(key(day)) || ''; }
function saveMemo(day, val){ localStorage.setItem(key(day), val); }

function buildCalendar(){
  const days = document.getElementById('days');
  const html = [];
  const startBlank = 4; // 2026 Jan starts Thu
  for(let i=0; i<startBlank; i++){
    html.push('<div class="day-cell empty"></div>');
  }

  data.forEach(item=>{
    const d = new Date(item.date + 'T00:00:00');
    const w = d.getDay();
    const cls = w === 0 ? 'sunday' : w === 6 ? 'saturday' : '';
    const memo = getMemo(item.day);
    html.push(`
      <div class="day-cell ${cls}" onclick="selectDay(${item.day})">
        <div class="date-row">
          <div class="date-num">${item.day}</div>
          <div>
            <div class="rokuyo">${item.rokuyo}</div>
            <div class="lunar">${item.lunar}</div>
          </div>
        </div>
        ${item.event ? `<div class="event ${item.eventColor}">${item.event}</div>` : ''}
        ${memo ? '<div class="memo-mark">メモあり</div>' : ''}
      </div>
    `);
  });

  // memo column visual cells
  const totalCells = startBlank + data.length;
  const rows = Math.ceil(totalCells / 7);
  for(let r=0; r<rows; r++){
    html.splice((r+1)*7 + r, 0, '<div class="memo-cell"></div>');
  }

  days.innerHTML = html.join('');
}

function selectDay(day){
  selected = data.find(x=>x.day === day);
  renderDetail();
}

function renderDetail(){
  const detail = document.getElementById('detail');
  const memo = document.getElementById('memo');
  detail.innerHTML = `
    <h2>${selected.day}日</h2>
    <div class="meta-pills">
      <span class="pill">${selected.rokuyo}</span>
      <span class="pill">${selected.lunar}</span>
      <span class="pill">沖縄行事</span>
    </div>
    <p><strong>${selected.event || '行事情報なし'}</strong></p>
    <p>${selected.note}</p>
  `;
  memo.value = getMemo(selected.day);
}

document.getElementById('save').addEventListener('click', ()=>{
  saveMemo(selected.day, document.getElementById('memo').value);
  buildCalendar();
  alert('この端末に保存しました');
});

buildCalendar();
renderDetail();
